PostgreSQL.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the PostgreSQL container

Container_Boundary(PostgreSQL, "PostgreSQL") {
    Component(Primary_Database_Instance, "Primary Database Instance", "PostgreSQL 15, AWS RDS", "Relational datastore ensuring EU data residency, transactional integrity, and handling write operations.")
    Component(Read_Replica_Instance, "Read Replica Instance", "PostgreSQL 15, AWS RDS", "Read replica instance offloading query read operations.")
    Component(Connection_Pooler, "Connection Pooler", "PgBouncer", "Manages and optimizes connections between core services and database instances.")
}

Rel(Connection_Pooler, Primary_Database_Instance, "Routes queries", "PostgreSQL Wire Protocol over TLS 1.3")
Rel(Connection_Pooler, Read_Replica_Instance, "Routes queries", "PostgreSQL Wire Protocol over TLS 1.3")
Rel(Primary_Database_Instance, Read_Replica_Instance, "Asynchronous replication", "SSL/TLS")

@enduml

Message Broker.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Message Broker container

Container_Boundary("Message Broker", "Message Broker") {
    Component("Event Bus", "Event Bus", "Kafka Cluster", "Handles high-throughput asynchronous event streaming and domain event distribution.")
    Component("Schema Registry", "Schema Registry", "Confluent Schema Registry / Apicurio Registry", "Enforces schema evolution and regex-based PII sanitization.")
    Component("DLQ Handler", "DLQ Handler", "Kafka Consumer Group + Storage", "Forwards unacknowledged and failed messages after max retries.")
}

Rel("Event Bus", "DLQ Handler", "Forwards unacknowledged/failed messages after max retries", "Kafka Protocol")

@enduml
